function checkPlatformConfig(homebridge, platform){
    var configJSON = require(homebridge.user.configPath());
    var platforms = configJSON.platforms;
    for(var i in platforms) {
        if(platforms[i]['platform'] === platform) {
            return true;
        }
    }
    return false;
}

